const e="shiv-college-of-education-fest",u=null,n="Read from the 5-page 'Rules and Regulation' PDF of Shiv College of Education; it was checked against the downloaded original. The rules print only item rules: no dates, venue, fees, entry steps, judging marks, ranks or prizes, no edition year and no contact. The topics of the four Elocution subjects are copied. Sarvotam Shiksharthi (Purus) and (Mahila) are written as one competition.",t={Title:"Rules & Criteria",Subtitle:"Shiv College of Education - youth festival item rules",NoticeTitle:"Please Read Before Registering",Notice:"Each college or institute sends the number of participants set for each item. Several topics are given on the spot or 24 hours before. Dates and venue: {{FestDates}} / {{Venue}}.",Notes:["The rules are signed by the Director Youth Welfare.","Directors and Principals must screen the script of every stage item and make sure nothing is vulgar or obscene."],Sections:[{Key:"general",Title:"General",Items:["The rules cover 23 numbered items: stage, spoken, craft and personality items.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified.","The medium of expression is Hindi or English unless an item says otherwise (Nukad Natak and Group Improvisation: Hindi only).","Directors and Principals are asked to screen the script of the item to be staged and make sure nothing is vulgar or obscene (printed in Group Improvisation).","Most craft and art items are conducted on the spot, and each participant brings the material the item needs.","The rules print no judging marks or prizes; the signing authority is the Director Youth Welfare."]},{Key:"eligibility",Title:"Who may enter",Items:["A college or institute sends the number of participants set for each item: usually one participant, or a team of two for Debate, Quiz and Best Out of Waste.","Solo Dance: a college or institute can enter one participant, boy or girl.","Group Song: a team of 6 participants and 3 accompanists only.","Group Dance: a team of at most 10 participants if the music is live, otherwise only 8 participants if the music is on a track.","Nukad Natak: a team of not more than 9 participants and 2 accompanists only.","Group Improvisation: one team of 8 to 10 participants; two accompanists are allowed; the faculty may also play the teacher in the performance.","Debate: one team of 2 speakers.","Quiz: a team of two persons.","Best Out of Waste: two participants perform jointly.","Teacher on Leave: one participant, and the teaching subject must be mentioned.","Sarvotam Shiksharthi (Purus): one male participant. Sarvotam Shiksharthi (Mahila): one female participant."]},{Key:"registration",Title:"How to enter",Items:["The rules do not print how to register, entry fees or last dates. Contact the organising college: {{OrganiserContact}}.","Debate: the side (for or against the motion) of each speaker must be told to the stage secretary before the competition starts."]},{Key:"dates",Title:"Dates and venue",Items:["Dates: {{FestDates}}. Venue: {{Venue}}. The document does not print them."]},{Key:"judging",Title:"Judging",Items:["No judging criteria or marks are printed.","Aaj Ka Vichar: neat and clean handwriting carries bonus marks.","Quiz: the decision of the Quiz Master is final on the correctness of an answer.","Judges examine the waste material before Best Out of Waste starts and the pots, sheets and paper are checked or signed by organisers or judges where stated."]}],Documents:[{Title:"Rules and Regulation (PDF)",Url:"https://shivcollegeofeducation.com/RULES_AND_REGULATION.pdf"}]},o=[{ParticipantType:"Team",Source:"Items 1, 3, 4, 5, 8, 10, 16",Sections:{About:null,TimeAndFormat:null,Rules:["Team sizes: Group Song 6 plus 3 accompanists; Group Dance up to 10 (live music) or 8 (track); Nukad Natak up to 9 plus 2 accompanists; Group Improvisation 8 to 10 plus 2 accompanists; Debate 2 speakers; Quiz 2 persons; Best Out of Waste 2 participants."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Team sizes: Group Song 6 plus 3 accompanists; Group Dance up to 10 (live music) or 8 (track); Nukad Natak up to 9 plus 2 accompanists; Group Improvisation 8 to 10 plus 2 accompanists; Debate 2 speakers; Quiz 2 persons; Best Out of Waste 2 participants.`},{ParticipantType:"Individual",Source:"Items 2, 6, 7, 9, 11-15, 17-23",Sections:{About:null,TimeAndFormat:null,Rules:["Each college or institute sends one participant in every individual item."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- Each college or institute sends one participant in every individual item.`}],a=[],i=JSON.parse('[{"Title":"Group Song","Source":"1. Group song (Women Empowerment)","Sections":{"About":["Group song on the theme Women Empowerment."],"TimeAndFormat":["Not less than 6 minutes and not more than 8 minutes."],"Rules":["A team of 6 participants and 3 accompanists only.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Group song on the theme Women Empowerment.\\n\\n## Time and format\\n- Not less than 6 minutes and not more than 8 minutes.\\n\\n## Rules\\n- A team of 6 participants and 3 accompanists only.\\n- Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."},{"Title":"Solo Dance","Source":"2. Solo Dance","Sections":{"About":["Folk dance for one participant."],"TimeAndFormat":["Not less than 4 minutes and not more than 6 minutes."],"Rules":["A college or institute can enter one participant, boy or girl.","Only folk dance can be performed, such as Haryanvi, Punjabi or Rajasthani.","Two accompanists are allowed.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."],"Allowed":["Recorded music."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Folk dance for one participant.\\n\\n## Time and format\\n- Not less than 4 minutes and not more than 6 minutes.\\n\\n## Rules\\n- A college or institute can enter one participant, boy or girl.\\n- Only folk dance can be performed, such as Haryanvi, Punjabi or Rajasthani.\\n- Two accompanists are allowed.\\n- Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified.\\n\\n## Allowed\\n- Recorded music."},{"Title":"Group Dance","Source":"3. Group Dance","Sections":{"About":null,"TimeAndFormat":["Not less than 7 minutes and not more than 9 minutes."],"Rules":["A college or institute can send a team of at most 10 participants if the music is live, otherwise only 8 participants if the music is on a track.","The dance can be folk, general or any acceptable form.","The track played can be filmy or non-filmy.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."],"Allowed":["Recorded music and fusion music."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Not less than 7 minutes and not more than 9 minutes.\\n\\n## Rules\\n- A college or institute can send a team of at most 10 participants if the music is live, otherwise only 8 participants if the music is on a track.\\n- The dance can be folk, general or any acceptable form.\\n- The track played can be filmy or non-filmy.\\n- Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified.\\n\\n## Allowed\\n- Recorded music and fusion music."},{"Title":"Nukad Natak","Source":"4. Nukad Natak (Value Education)","Sections":{"About":["Street play on the theme Value Education."],"TimeAndFormat":["Not less than 10 minutes and not more than 12 minutes."],"Rules":["A team of not more than 9 participants and 2 accompanists only.","Hindi is the medium of expression.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."],"Allowed":null,"NotAllowed":["Lights, microphones and make-up."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Street play on the theme Value Education.\\n\\n## Time and format\\n- Not less than 10 minutes and not more than 12 minutes.\\n\\n## Rules\\n- A team of not more than 9 participants and 2 accompanists only.\\n- Hindi is the medium of expression.\\n- Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified.\\n\\n## Not allowed\\n- Lights, microphones and make-up."},{"Title":"Group Improvisation","Source":"5. Group Improvisation (Teaching Pedagogy)","Sections":{"About":["Improvised group performance on teaching pedagogy."],"TimeAndFormat":["Not less than 8 minutes and not more than 10 minutes."],"Rules":["A college can enter only one team of 8 to 10 participants.","The medium of the item can be Hindi only.","Two accompanists are allowed.","Vulgarity and obscenity lead to disqualification.","Directors and Principals must screen the script of the item to be staged and make sure nothing is vulgar or obscene.","The team first looks like a class and then acts as a drama, and all participants should be active.","The faculty may also play the role of teacher in the performance."],"Allowed":["Make-up, drapery and background music."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Improvised group performance on teaching pedagogy.\\n\\n## Time and format\\n- Not less than 8 minutes and not more than 10 minutes.\\n\\n## Rules\\n- A college can enter only one team of 8 to 10 participants.\\n- The medium of the item can be Hindi only.\\n- Two accompanists are allowed.\\n- Vulgarity and obscenity lead to disqualification.\\n- Directors and Principals must screen the script of the item to be staged and make sure nothing is vulgar or obscene.\\n- The team first looks like a class and then acts as a drama, and all participants should be active.\\n- The faculty may also play the role of teacher in the performance.\\n\\n## Allowed\\n- Make-up, drapery and background music."},{"Title":"Elocution","Source":"6. Elocution","Sections":{"About":null,"TimeAndFormat":["Not less than 4 minutes and not more than 6 minutes."],"Rules":["Each college is represented by one speaker.","The medium of expression is Hindi or English.","The participant prepares all four topics and speaks on one, decided by draw of lots on the spot.","Topics: Role of teacher in nation building; A teacher: from gurukul to convent school; The changing relations of teacher-taught; The present education system and its worth."],"Allowed":null,"NotAllowed":["Paper reading."],"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Not less than 4 minutes and not more than 6 minutes.\\n\\n## Rules\\n- Each college is represented by one speaker.\\n- The medium of expression is Hindi or English.\\n- The participant prepares all four topics and speaks on one, decided by draw of lots on the spot.\\n- Topics: Role of teacher in nation building; A teacher: from gurukul to convent school; The changing relations of teacher-taught; The present education system and its worth.\\n\\n## Not allowed\\n- Paper reading."},{"Title":"Poetic Recitation","Source":"7. Poetic Recitation","Sections":{"About":null,"TimeAndFormat":["Not less than 3 minutes and not more than 4 minutes."],"Rules":["Each college can send one participant only.","The medium of recitation is Hindi or English.","The content of the poem should not be vulgar or cheap."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Not less than 3 minutes and not more than 4 minutes.\\n\\n## Rules\\n- Each college can send one participant only.\\n- The medium of recitation is Hindi or English.\\n- The content of the poem should not be vulgar or cheap."},{"Title":"Debate","Source":"8. Debate","Sections":{"About":null,"TimeAndFormat":["Not less than 4 minutes and not more than 6 minutes for each participant."],"Rules":["A college can send one team of 2 speakers.","The medium of expression is Hindi or English.","One speaker speaks for the motion and the other against. Tell the stage secretary before the competition starts.","The subject is announced 24 hours before the programme. Participants speak after drawing lots to decide who speaks first, second and so on.","Vulgarity or obscenity must be avoided in action and gesture."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Not less than 4 minutes and not more than 6 minutes for each participant.\\n\\n## Rules\\n- A college can send one team of 2 speakers.\\n- The medium of expression is Hindi or English.\\n- One speaker speaks for the motion and the other against. Tell the stage secretary before the competition starts.\\n- The subject is announced 24 hours before the programme. Participants speak after drawing lots to decide who speaks first, second and so on.\\n- Vulgarity or obscenity must be avoided in action and gesture."},{"Title":"Teacher on Leave","Source":"9. Teacher on Leave","Sections":{"About":["A participant teaches a class on the spot in place of a teacher on leave."],"TimeAndFormat":["Maximum time allowed is 10 minutes."],"Rules":["Each college can send one participant, and their teaching subject must be mentioned.","The topic is given to the participant on the spot.","The presentation should be relevant to the subject of the teacher on leave and suit the class.","Core teaching skills such as questioning, illustration with examples, explanation and stimulation are to be followed.","Interaction with the students is observed."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- A participant teaches a class on the spot in place of a teacher on leave.\\n\\n## Time and format\\n- Maximum time allowed is 10 minutes.\\n\\n## Rules\\n- Each college can send one participant, and their teaching subject must be mentioned.\\n- The topic is given to the participant on the spot.\\n- The presentation should be relevant to the subject of the teacher on leave and suit the class.\\n- Core teaching skills such as questioning, illustration with examples, explanation and stimulation are to be followed.\\n- Interaction with the students is observed."},{"Title":"Quiz","Source":"10. Quiz","Sections":{"About":null,"TimeAndFormat":null,"Rules":["Each institute can send a team of two persons.","The medium of the quiz is English or Hindi.","A written preliminary round selects the teams for the final; the final round is oral.","The specific rules on evaluation, time to reply to an answer and the type of round are given before the competition starts.","The decision of the Quiz Master is final on the correctness of the answer.","The quiz is based on general awareness and the B.Ed syllabus."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Rules\\n- Each institute can send a team of two persons.\\n- The medium of the quiz is English or Hindi.\\n- A written preliminary round selects the teams for the final; the final round is oral.\\n- The specific rules on evaluation, time to reply to an answer and the type of round are given before the competition starts.\\n- The decision of the Quiz Master is final on the correctness of the answer.\\n- The quiz is based on general awareness and the B.Ed syllabus."},{"Title":"Extempore","Source":"11. Extempore (For and Against)","Sections":{"About":null,"TimeAndFormat":["The speaker has 2 minutes: one minute for and one minute against the topic."],"Rules":["Each college or institute may send one participant.","Topics are given on the spot, 2 minutes before the event.","The matter can be in Hindi or English.","Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- The speaker has 2 minutes: one minute for and one minute against the topic.\\n\\n## Rules\\n- Each college or institute may send one participant.\\n- Topics are given on the spot, 2 minutes before the event.\\n- The matter can be in Hindi or English.\\n- Vulgarity or obscenity must be avoided in action, costume and gesture; otherwise the entry is disqualified."},{"Title":"Aaj Ka Vichar","Source":"12. Aaj Ka Vichar","Sections":{"About":["A thought of the day written by the participant."],"TimeAndFormat":null,"Rules":["Each college can send one participant.","The participant writes it on the white marker board and also submits it in writing on A4 paper.","The theme is given on the spot, 10 minutes before the event.","The idea should be widely accepted and according to the theme."],"Allowed":null,"NotAllowed":null,"Judging":["Neat and clean handwriting carries bonus marks."],"Points":null,"Notes":null},"Markdown":"## About this competition\\n- A thought of the day written by the participant.\\n\\n## Rules\\n- Each college can send one participant.\\n- The participant writes it on the white marker board and also submits it in writing on A4 paper.\\n- The theme is given on the spot, 10 minutes before the event.\\n- The idea should be widely accepted and according to the theme.\\n\\n## Judging\\n- Neat and clean handwriting carries bonus marks."},{"Title":"My Dream Teaching Aid","Source":"13. My Dream Teaching Aid","Sections":{"About":null,"TimeAndFormat":["The time limit is 60 minutes (1 hour)."],"Rules":["Each college can send one participant.","The teaching aid should suit the level of the students and the teaching subject.","It should be properly visible and audible and convey the message for which it is prepared.","The participant brings the material with which the teaching aid is prepared."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- The time limit is 60 minutes (1 hour).\\n\\n## Rules\\n- Each college can send one participant.\\n- The teaching aid should suit the level of the students and the teaching subject.\\n- It should be properly visible and audible and convey the message for which it is prepared.\\n- The participant brings the material with which the teaching aid is prepared."},{"Title":"Clay Modeling","Source":"14. Clay Modeling","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send one participant.","The subject is a portrayal or an object or theme, given on the spot.","Participants bring their own material as needed."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send one participant.\\n- The subject is a portrayal or an object or theme, given on the spot.\\n- Participants bring their own material as needed."},{"Title":"Pot Decoration","Source":"15. Pot Decoration","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send one participant.","The event is conducted on the spot.","Participants bring their own material as needed.","The department provides the pots on the spot."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send one participant.\\n- The event is conducted on the spot.\\n- Participants bring their own material as needed.\\n- The department provides the pots on the spot."},{"Title":"Best Out of Waste","Source":"16. Best Out of Waste","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send two participants to perform jointly.","The topic is announced 24 hours before the event, and the event is conducted on the spot.","Participants bring their own waste material.","Only the waste material examined by the judges before the start may be used."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send two participants to perform jointly.\\n- The topic is announced 24 hours before the event, and the event is conducted on the spot.\\n- Participants bring their own waste material.\\n- Only the waste material examined by the judges before the start may be used."},{"Title":"Rangoli","Source":"17. Rangoli","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send one participant.","The event is conducted on the spot, and participants bring their own material.","Participants make the rangoli within the space provided by the organisers or judges."],"Allowed":["Only one medium: flower petals, saw-dust, pulses or rice, without pasting."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send one participant.\\n- The event is conducted on the spot, and participants bring their own material.\\n- Participants make the rangoli within the space provided by the organisers or judges.\\n\\n## Allowed\\n- Only one medium: flower petals, saw-dust, pulses or rice, without pasting."},{"Title":"Collage","Source":"18. Collage","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send one participant.","The topic is announced 24 hours before the event, and the event is conducted on the spot.","Participants bring their own scissors and other material.","The organisers do not supply blank drawing sheets or sticking paste."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send one participant.\\n- The topic is announced 24 hours before the event, and the event is conducted on the spot.\\n- Participants bring their own scissors and other material.\\n- The organisers do not supply blank drawing sheets or sticking paste."},{"Title":"Poster Making","Source":"19. Poster Making","Sections":{"About":null,"TimeAndFormat":["Duration is not more than 2 hours 30 minutes."],"Rules":["Each college can send one participant.","The event is conducted on the spot, on the subject given by the organisers or judges.","Participants bring their own material. The organisers or judges sign the blank sheet before the start."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Duration is not more than 2 hours 30 minutes.\\n\\n## Rules\\n- Each college can send one participant.\\n- The event is conducted on the spot, on the subject given by the organisers or judges.\\n- Participants bring their own material. The organisers or judges sign the blank sheet before the start."},{"Title":"Mehandi","Source":"20. Mehandi","Sections":{"About":null,"TimeAndFormat":["The duration is one hour only."],"Rules":["Each college can send one participant only.","Competitors bring their own material. The participant may apply mehandi on their own hand or arrange another student for this.","An oral explanation is asked on the spot.","Herbal henna is to be used."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- The duration is one hour only.\\n\\n## Rules\\n- Each college can send one participant only.\\n- Competitors bring their own material. The participant may apply mehandi on their own hand or arrange another student for this.\\n- An oral explanation is asked on the spot.\\n- Herbal henna is to be used."},{"Title":"On the Spot Painting","Source":"21. On the Spot Painting","Sections":{"About":null,"TimeAndFormat":["Two hours 30 minutes are allowed to each participant."],"Rules":["Each college can send one participant.","The subject is a landscape, a portrait or a composition, given by the organisers or judges.","The size is half imperial drawing paper, 22 x 15 inches, signed by the organisers or judges before the start.","Participants bring their own material."],"Allowed":["Oil, water, pastel or poster colours."],"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## Time and format\\n- Two hours 30 minutes are allowed to each participant.\\n\\n## Rules\\n- Each college can send one participant.\\n- The subject is a landscape, a portrait or a composition, given by the organisers or judges.\\n- The size is half imperial drawing paper, 22 x 15 inches, signed by the organisers or judges before the start.\\n- Participants bring their own material.\\n\\n## Allowed\\n- Oil, water, pastel or poster colours."},{"Title":"Sarvotam Shiksharthi","Source":"22. and 23. Sarvotam Shiksharthi (Purus) and (Mahila)","Sections":{"About":["Best student contest in three knock-out rounds, held separately for men (Purus) and women (Mahila)."],"TimeAndFormat":null,"Rules":["Each college can send one participant: a male for Purus, a female for Mahila.","The event has 3 rounds, and every round is a knock-out round.","In the first round the participant comes on stage in their own style and own wardrobe.","The second round is a questioning round by the judges.","The third round is a performance round: 2 minutes to show a talent.","Judgement is based on the overall performance of the participant."],"Allowed":null,"NotAllowed":null,"Judging":null,"Points":null,"Notes":null},"Markdown":"## About this competition\\n- Best student contest in three knock-out rounds, held separately for men (Purus) and women (Mahila).\\n\\n## Rules\\n- Each college can send one participant: a male for Purus, a female for Mahila.\\n- The event has 3 rounds, and every round is a knock-out round.\\n- In the first round the participant comes on stage in their own style and own wardrobe.\\n- The second round is a questioning round by the judges.\\n- The third round is a performance round: 2 minutes to show a talent.\\n- Judgement is based on the overall performance of the participant."}]'),s=[],r=[{Key:"FestDates",Kind:"date",Label:"Festival dates",Value:"To be announced (not printed in the rules)",Source:"Not printed"},{Key:"Venue",Kind:"address",Label:"Festival venue",Value:{Name:"To be announced",Address:"",City:"",MapUrl:"",Directions:""},Source:"Not printed"},{Key:"OrganiserContact",Kind:"text",Label:"Contact for entries",Value:"Shiv College of Education (contact details are not printed in the rules)",Source:"Not printed"}],l=[{Claim:"Shiv College of Education youth festival item rules (23 items).",SourceType:"Primary - the event's own rules document",Source:"Shiv College of Education, Rules and Regulation",Url:"https://shivcollegeofeducation.com/RULES_AND_REGULATION.pdf"}],c={TemplateKey:e,Year:null,Note:n,Page:t,ParticipantTypes:o,AgeGroups:a,Competitions:i,CompetitionAgeGroups:s,Variables:r,Evidence:l};export{a as AgeGroups,s as CompetitionAgeGroups,i as Competitions,l as Evidence,n as Note,t as Page,o as ParticipantTypes,e as TemplateKey,r as Variables,u as Year,c as default};
